#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ProgramOutput {
    pub first_sum: i32,
    pub second_sum: i32,
}

pub fn run(n: i32) -> ProgramOutput {
    let mut v = PersistentVector::new();
    let mut i = 0i32;

    while i < n {
        v = v.push_back(i + 1);
        i += 1;
    }

    let first_sum = sum_vector(&v);

    let mut v2 = PersistentVector::new();
    let mut index = 0usize;
    while index < v.size() {
        v2 = v2.push_back(v[index].wrapping_mul(2));
        index += 1;
    }

    let second_sum = sum_vector(&v2);

    ProgramOutput {
        first_sum,
        second_sum,
    }
}

fn sum_vector(vector: &PersistentVector<i32>) -> i32 {
    let mut sum = 0i32;

    for value in vector.iter() {
        sum = sum.wrapping_add(*value);
    }

    sum
}

